// Hide the console window for the GUI in release builds on Windows.
#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

mod category;
mod cli;
mod compare;
mod delete;
mod dupes;
mod filter;
mod model;
mod platform;
mod remote;
mod scan;
mod snapshot;
mod swrender;
mod ui;
mod util;

/// 64×64 RGBA app icon (generated by assets/make_icon.py).
pub const ICON_RGBA: &[u8] = include_bytes!("../assets/icon_64.rgba");

fn main() -> eframe::Result {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.first().map(String::as_str) == Some("--cli") {
        #[cfg(windows)]
        unsafe {
            // Re-attach to the parent console so CLI output is visible.
            windows_sys::Win32::System::Console::AttachConsole(u32::MAX);
        }
        std::process::exit(cli::run(&args[1..]));
    }
    let initial = if args.iter().any(|a| a == "--compare") { None } else { args.iter().find(|a| !a.starts_with('-')).map(std::path::PathBuf::from) };

    let force_gl = args.iter().any(|a| a == "--opengl") || std::env::var_os("SIZEMATTERS_OPENGL").is_some();
    let make = |renderer: eframe::Renderer| {
        let mut o = eframe::NativeOptions {
            viewport: egui::ViewportBuilder::default()
                .with_title("SizeMatters")
                .with_icon(egui::IconData { rgba: ICON_RGBA.to_vec(), width: 64, height: 64 })
                .with_inner_size([1480.0, 900.0])
                .with_min_inner_size([900.0, 560.0]),
            renderer,
            ..Default::default()
        };
        // Never touch Vulkan on Windows: some Intel/older drivers crash while merely
        // enumerating Vulkan adapters (igvk64.dll access violation). DirectX 12 only.
        // One queued frame instead of two: clicks and hovers feel immediate.
        o.wgpu_options.surface = eframe::egui_wgpu::SurfaceConfig::LOW_LATENCY;
        if platform::is_remote_session() {
            // Over Remote Desktop, waiting for vsync queues frames behind the remote
            // compositor's slow refresh, so hover feedback trails the mouse. Present now.
            o.wgpu_options.surface.present_mode = eframe::wgpu::PresentMode::AutoNoVsync;
        }
        #[cfg(windows)]
        if let eframe::egui_wgpu::WgpuSetup::CreateNew(c) = &mut o.wgpu_options.wgpu_setup {
            c.instance_descriptor.backends = eframe::wgpu::Backends::DX12;
        }
        o
    };
    let run = |renderer: eframe::Renderer| {
        let initial = initial.clone();
        eframe::run_native("SizeMatters", make(renderer), Box::new(move |cc| Ok(Box::new(ui::App::new(&cc.egui_ctx, initial)))))
    };
    // Remote Desktop: CPU renderer that sends only changed tiles (see swrender.rs).
    let software = args.iter().any(|a| a == "--software")
        || (platform::is_remote_session() && !args.iter().any(|a| a == "--gpu"));
    if software {
        if let Err(e) = swrender::run(initial.clone()) {
            fatal(&format!("Software renderer: {e}"));
        }
        return Ok(());
    }
    if force_gl {
        if let Err(e) = run(eframe::Renderer::Glow) {
            fatal(&format!("OpenGL: {e}\n\nOpenGL is often unavailable over Remote Desktop; use the normal launch there."));
        }
        return Ok(());
    }
    let result = match run(eframe::Renderer::Wgpu) {
        Ok(()) => Ok(()),
        Err(e) => {
            // No usable DirectX 12 adapter: fall back to OpenGL.
            eprintln!("GPU renderer failed ({e}); retrying with OpenGL");
            run(eframe::Renderer::Glow).map_err(|e2| (e, Some(e2)))
        }
    }
    .map_err(|(e, e2)| format!("DirectX 12: {e}{}", e2.map(|x| format!("\nOpenGL: {x}")).unwrap_or_default()));
    if let Err(msg) = &result {
        fatal(msg);
    }
    Ok(())
}

/// Show a startup error instead of silently exiting (release builds have no console).
fn fatal(msg: &str) {
    let _ = rfd::MessageDialog::new()
        .set_title("SizeMatters could not start")
        .set_description(format!("The graphics renderer failed to start.\n\n{msg}\n\nTry the other launch mode, or update your graphics driver."))
        .set_level(rfd::MessageLevel::Error)
        .show();
}
